    # Found 3 potential faults. Type-codes: 101, 205
    @timeout_decorator.timeout(60)
    def test_73_post_on_offline_showsFaults_101_205(self):
        
        headers = {}
        headers["content-type"] = "application/json"
        body = " { " + \
            " \"email\" : \"viewer\", " + \
            " \"password\" : \"V1ewer-Bamf-Thesis-2026\" " + \
            " } "
        res_viewer = requests \
                .post("http://localhost:8221/login", 
                    headers=headers, data=body, allow_redirects=False, verify=False)
        token_viewer =  res_viewer.json()["token"]
        
        auth_viewer = "Bearer " + token_viewer
        headers = {}
        headers["content-type"] = "application/json"
        body = " { " + \
            " \"email\" : \"admin\", " + \
            " \"password\" : \"Adm1n-Bamf-Thesis-2026\" " + \
            " } "
        res_admin = requests \
                .post("http://localhost:8221/login", 
                    headers=headers, data=body, allow_redirects=False, verify=False)
        token_admin =  res_admin.json()["token"]
        
        auth_admin = "Bearer " + token_admin
        
        # Fault101. Received A Response From API With A Structure/Data That Is Not Matching Its Schema. Type: validation.response.status.unknown Response status 403 not defined for path '/api/v1/audit/recordings'.
        headers = {}
        headers["Authorization"] = auth_viewer # viewer
        headers['Accept'] = "application/json"
        res_0 = requests \
                .get(self.baseUrlOfSut + "/api/v1/audit/recordings?" + 
                    "resource_name=az5icRK&" + 
                    "recording_type=j96fX&" + 
                    "since=1987-08-11T22%3A60%3A29.112Z",
                    headers=headers, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_0.status_code == 403
        assert "application/json" in res_0.headers["content-type"]
        assert res_0.json()["detail"] == "Admin or audit access required"
        
        headers = {}
        headers["Authorization"] = auth_admin # admin
        headers['Accept'] = "application/json"
        res_1 = requests \
                .get(self.baseUrlOfSut + "/api/v1/audit/recordings?" + 
                    "user_email=%7B%0A++++++++++++++++++++%22QozPpjwDe%22%3A%22%22%0A++++++++++++++++++++%7D&" + 
                    "since=1936-03-20T22%3A22%3A49Z&" + 
                    "until=2073-07-17T10%3A18%3A29Z",
                    headers=headers, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_1.status_code == 200
        assert "application/json" in res_1.headers["content-type"]
        assert len(res_1.json()["items"]) == 0
        assert res_1.json()["next_cursor"] is None
        assert res_1.json()["has_more"] == False
        
        # Fault101. Received A Response From API With A Structure/Data That Is Not Matching Its Schema. Type: validation.response.status.unknown Response status 401 not defined for path '/api/v1/agents/{agent_id}/instance/{instance_id}/offline'.
        # Fault205. Wrongly Not Recognized as Authenticated.
        headers = {}
        headers["X-Bamf-Client-Cert"] = "null"
        headers["Authorization"] = auth_admin # admin
        headers['Accept'] = "application/json"
        res_2 = requests \
                .post(self.baseUrlOfSut + "/api/v1/agents/tI0fz78Z7XDapRlU/instance/7ArQ/offline",
                    headers=headers, timeout=EM_HTTP_TIMEOUT_S, verify=False)
        
        assert res_2.status_code == 401
        assert "www-authenticate" not in res_2.headers
        assert "application/json" in res_2.headers["content-type"]
        assert res_2.json()["detail"] == "Invalid certificate format"


